@Injectable()
export class AbacGuard implements CanActivate {
  async canActivate(ctx: ExecutionContext) {
    const req = ctx.switchToHttp().getRequest();
    const user = req.user;                 // role / scope(regionPath|selfId) / perms[]
    const { resource, action } = metaOf(ctx); // 由 @Abac('providers', 'review') 注入
    // 1 位阶：只读账号拒绝写动作
    if (user.readonly && !READONLY_OK.has(action)) return false;
    // 2 功能权限
    if (!user.perms.includes(permKey(resource, action))) return false;
    // 3 数据作用域：注入 where（regionPath 前缀 / selfId）
    req.scopeWhere = buildScopeWhere(user);
    return true;
  }
}

enum RoleType { USER SERVICE_PROVIDER AGENT ADMIN }
model User { id String @id @default(cuid()) username String @unique password String role RoleType name String phone String? regionPath String? // 隔离前缀，如 '乌鲁木齐/天山区' status Status tier MemberTier // USER 的会员等级 balance Int @default(0) points Int @default(0) createdAt DateTime @default(now()) agent Agent? provider ServiceProvider? }
model Region { id String @id @default(cuid()) name String level RegionLevel // PROVINCE / CITY / DISTRICT regionPath String @unique // '乌鲁木齐/天山区' agentId String? agent Agent? @relation(fields: [agentId], references: [id]) }
model Agent { id String @id @default(cuid()) userId String @unique user User @relation(fields: [userId], references: [id]) regionId String region Region @relation(fields: [regionId], references: [id]) status AgentStatus // NORMAL / REVIEW / DISABLED monthlyFlow Int @default(0) }
model ServiceProvider { id String @id @default(cuid()) userId String @unique user User @relation(fields: [userId], references: [id]) type String // 婚庆主持 / 摄影摄像 ... regionPath String status ProviderStatus // PENDING_REVIEW / APPROVED / REJECTED / REVIEWING / UPGRADING qualification Json? // 资质项数组 }
model Service { id String @id @default(cuid()) providerId String name String type String price Int status ServiceStatus // ON_SALE / DRAFT / OFF_SHELF template Boolean @default(false) // 模板审核复用 }
model Order { id String @id @default(cuid()) orderNo String @unique userId String providerId String serviceId String amount Int status OrderStatus // PENDING_ACCEPT / IN_PROGRESS / DONE / AFTER_SALE createdAt DateTime @default(now()) }
model Wallet { id String @id @default(cuid()) ownerType String // AGENT / PROVIDER ownerId String balance Int frozen Int totalFlow Int }
model Ledger { id String @id @default(cuid()) walletId String type LedgerType // IN / PENDING / OUT amount Int balanceAfter Int createdAt DateTime @default(now()) }
model Withdrawal { id String @id @default(cuid()) providerId String amount Int account String status ReviewStatus // PENDING / APPROVED / REJECTED createdAt DateTime @default(now()) }
model Feedback { id String @id @default(cuid()) no String @unique kind String // 服务投诉 / 价格争议 / 服务满意 ... userId String targetId String status FeedbackStatus // NEGOTIATING / HANDLED / UPGRADED / CLOSED content String createdAt DateTime @default(now()) }
model Message { id String @id @default(cuid()) title String kind MessageKind // 订单 / 服务 / 评价 / 权益 / 公告 / 系统通知 scope String // 全平台 / 区域 / 指定用户 status MessageStatus // UNREAD / READ / PENDING_REVIEW / PUBLISHED body String? createdAt DateTime @default(now()) }
model Role { id String @id @default(cuid()) name String layer LayerType // CONSOLE / AGENT / PROVIDER type RoleKind // BUILTIN / CUSTOM scope ScopeType // ALL / REGION / SELF perms String[] // 权限点 key 数组（10 域 28 点） level Int // 位阶：100 超级 / 90 运维 / 80 审核 / 80 财务 / 60 客服 accountCount Int @default(0) }
model UserRole { userId String roleId String @@id([userId, roleId]) }
model Coupon { id String @id @default(cuid()) title String amount Int validFrom DateTime validTo DateTime condition String? status CouponStatus }
model UserCoupon { id String @id @default(cuid()) userId String coupon Coupon @relation(fields: [couponId], references: [id]) couponId String used Boolean @default(false) }
